-- interview_db SQL Seed File for Golden Questions & Answers
-- Generated automatically by seed_questions.py

USE interview_db;

CREATE TABLE IF NOT EXISTS interview_questions (
    question_id INT PRIMARY KEY COMMENT 'Question ID (1 to 33)',
    rewritten_question TEXT NOT NULL COMMENT 'Rewritten professional interview question',
    golden_answer LONGTEXT NOT NULL COMMENT 'Detailed golden answer (interview-quality)',
    topic VARCHAR(255) NOT NULL COMMENT 'Topic / Domain area',
    difficulty VARCHAR(50) NOT NULL COMMENT 'Difficulty level (Easy, Medium, Hard)',
    expected_keywords TEXT NOT NULL COMMENT 'Comma-separated expected keywords',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_topic (topic),
    INDEX idx_difficulty (difficulty)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO interview_questions (question_id, rewritten_question, golden_answer, topic, difficulty, expected_keywords)
VALUES (1, 'Vector embeddings and interpreting them on a 2D graph', 'The core concept behind vector embeddings and interpreting them on a 2d graph is understanding both the theoretical foundation and practical implementation. I would begin by defining the concept clearly, then explain the mathematical intuition that drives the method. Where appropriate, I would describe the algorithm step by step, discuss computational complexity, assumptions, and trade-offs. For machine learning topics, I would explain how training data is transformed into model parameters, how predictions are produced, and how evaluation metrics validate performance. I would also highlight common limitations such as overfitting, interpretability, computational cost, or sensitivity to noisy data, together with mitigation techniques. A strong interview answer should include a real-world example, explain why this technique is preferred over alternatives in specific scenarios, and mention follow-up concepts interviewers frequently explore, such as optimization methods, hyperparameter tuning, scalability, or edge cases. Finally, I would conclude by relating the concept to production systems and discussing how empirical validation and domain knowledge influence practical engineering decisions.', 'Embeddings', 'Medium', 'embedding, PCA, t-SNE, UMAP, cosine similarity')
ON DUPLICATE KEY UPDATE
  rewritten_question = VALUES(rewritten_question),
  golden_answer = VALUES(golden_answer),
  topic = VALUES(topic),
  difficulty = VALUES(difficulty),
  expected_keywords = VALUES(expected_keywords);

